import type { AppConfig } from "awatif/templates";

// Hibbler frame example in the XZ work plane: beam A-B-C at 16 ft with a pinned
// wall connection at A, columns B-E and C-D fixed at the ground, a 2 k/ft
// uniform load on AB and a 10 k point load 8 ft from C. Imperial values from
// the source are converted to kN and m (1 ft = 0.3048 m, 1 k = 4.448 kN).
export const hibblerFrame: AppConfig = {
  points: [
    [0, 0, 4.8768], // 1 A, wall connection
    [3.6576, 0, 4.8768], // 2 B, 12 ft from A
    [6.096, 0, 4.8768], // 3 point load, 8 ft from B
    [8.5344, 0, 4.8768], // 4 C, 8 ft from load
    [3.6576, 0, 0], // 5 E, column base under B
    [8.5344, 0, 0], // 6 D, column base under C
  ],
  lines: [
    [1, 2], // beam AB
    [2, 3], // beam B to load point
    [3, 4], // beam load point to C
    [5, 2], // column EB
    [6, 4], // column DC
  ],

  gridLines: [
    {
      name: "Frame Grid",
      templateId: "grid-system",
      geometry: [],
      params: {
        x: [
          { id: "A", ordinate: 0, visible: true, bubble: "end" },
          { id: "B", ordinate: 3.6576, visible: true, bubble: "end" },
          { id: "P", ordinate: 6.096, visible: true, bubble: "end" },
          { id: "C", ordinate: 8.5344, visible: true, bubble: "end" },
        ],
        y: [{ id: "1", ordinate: 0, visible: true, bubble: "start" }],
        z: [
          { id: "Z1", ordinate: 0, visible: true, bubble: "end" },
          { id: "Z2", ordinate: 4.8768, visible: true, bubble: "end" },
        ],
      },
    },
  ],

  loadCases: ["Applied"],

  supports: [
    {
      name: "Wall Pin A",
      templateId: "point-support",
      geometry: [1],
      params: { type: "pinned" },
    },
    {
      name: "Fixed Bases D, E",
      templateId: "point-support",
      geometry: [5, 6],
      params: { type: "fixed" },
    },
  ],

  loads: [
    {
      name: "2 k/ft on AB",
      templateId: "distributed-load",
      geometry: [1],
      params: { w: 29.19, direction: "global-z" },
      loadCase: "Applied",
    },
    {
      name: "10 k on BC",
      templateId: "point-load",
      geometry: [3],
      params: { Fx: 0, Fy: 0, Fz: -44.48, Mx: 0, My: 0, Mz: 0 },
      loadCase: "Applied",
    },
  ],

  mesh: [
    {
      name: "Frame Mesh",
      templateId: "line-mesh",
      geometry: [1, 2, 3, 4, 5],
      params: { divisions: 8 },
    },
  ],

  design: [
    {
      // Placeholder: the source does not give member sections
      name: "Generic Steel Members",
      templateId: "generic-member",
      geometry: [1, 2, 3, 4, 5],
    },
  ],
};
